#!/usr/bin/env bash
# GENERATED FILE PRODUCER — see Fixtures/FixtureObservations.swift.
#
# Transcodes the owner's real OCR run (.local/ocr/ocr2_out.json — twelve photographed
# sleeves) into a committed Swift table. D-03-1: every string, confidence, angle and
# bounding box in Act I traces to a real photograph, never to invented text.
#
# .local/ is gitignored (public repo), so a fresh clone has no JSON. That is not an error:
# the committed table is the source of truth for anyone without the owner's local
# artefacts, and this script leaves it untouched rather than emitting a truncated one.
#
# Usage:
#   Scripts/generate-ocr-fixtures.sh
set -euo pipefail
cd "$(dirname "$0")/.."

SRC=".local/ocr/ocr2_out.json"
OUT_DIR="VinylSetBuilderCore/Sources/VinylSetBuilderCore/Fixtures"
OUT_FILE="$OUT_DIR/FixtureObservations.swift"

if [ ! -f "$SRC" ]; then
    echo "no $SRC — leaving the committed fixture table untouched" >&2
    exit 0
fi

mkdir -p "$OUT_DIR"
tmp_file="$(mktemp "$OUT_DIR/.FixtureObservations.swift.XXXXXX")"
trap 'rm -f "$tmp_file"' EXIT

python3 - "$SRC" "$tmp_file" <<'PY'
import json
import math
import sys

src, dest = sys.argv[1], sys.argv[2]

# Exactly the list CorePurityTests scans for, case-sensitive substring. The table below
# pipes 104 strings of arbitrary text off record sleeves straight into Core, and the purity
# guard reads doc comments too, so the generator gates its OWN output before writing.
BANNED = ["AVFoundation", "Vision", "UIKit", "AppKit", "SwiftUI",
          "SwiftData", "URLSession", "URLRequest", "URLProtocol"]

with open(src, encoding="utf-8") as handle:
    records = json.load(handle)

records.sort(key=lambda record: record["file"])

def swift_string(text):
    # Backslash first, then the quote, or the escaper eats its own output.
    escaped = text.replace("\\", "\\\\").replace('"', '\\"')
    escaped = escaped.replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
    return '"%s"' % escaped          # UTF-8 passes through; Swift source is UTF-8.

def num(value):
    return "%.10f" % round(float(value), 10)

total = sum(len(record["obs"]) for record in records)
trusted = sum(1 for record in records for o in record["obs"] if float(o["conf"]) >= 1.0)

lines = [
    "// GENERATED by Scripts/generate-ocr-fixtures.sh from .local/ocr/ocr2_out.json — DO NOT EDIT.",
    "// %d fixtures / %d observations / %d trusted (confidence >= 1.0). Angles are RADIANS."
    % (len(records), total, trusted),
    "",
    "import CoreGraphics",
    "",
    "/// The owner's twelve photographed sleeves, read once and committed. D-03-1.",
    "public enum FixtureObservations {",
    "    public static let all: [(file: String, observations: [TextObservation])] = [",
]

for record in records:
    lines.append("        (file: %s, observations: [" % swift_string(record["file"]))
    for o in record["obs"]:
        angle = float(o["angle"]) * math.pi / 180.0
        lines.append("            TextObservation(text: %s," % swift_string(o["text"]))
        lines.append("                            boundingBox: CGRect(x: %s, y: %s,"
                     % (num(o["x"]), num(o["y"])))
        lines.append("                                                width: %s, height: %s),"
                     % (num(o["w"]), num(o["h"])))
        lines.append("                            confidence: %s," % num(o["conf"]))
        lines.append("                            baselineAngle: %s)," % num(angle))
    lines.append("        ]),")

lines += ["    ]", "}", ""]
text = "\n".join(lines)

violations = []
for token in BANNED:
    if token not in text:
        continue
    carriers = ["%s: %r" % (record["file"], o["text"])
                for record in records for o in record["obs"] if token in o["text"]]
    if not carriers:
        carriers = ["the generator template itself"]
    violations += ["%s <- %s" % (token, carrier) for carrier in carriers]

if violations:
    sys.stderr.write("PURITY GATE FAILED — refusing to write %s\n" % dest)
    for v in violations:
        sys.stderr.write("  %s\n" % v)
    sys.exit(1)

with open(dest, "w", encoding="utf-8") as handle:
    handle.write(text)

sys.stderr.write("%d fixtures / %d observations / %d trusted\n" % (len(records), total, trusted))
PY

# Only replace when the content actually changed, so repeat runs are quiet and idempotent.
if [ -f "$OUT_FILE" ] && cmp -s "$tmp_file" "$OUT_FILE"; then
    echo "$OUT_FILE unchanged"
    exit 0
fi

mv "$tmp_file" "$OUT_FILE"
trap - EXIT
echo "wrote $OUT_FILE"
